# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: emit
def emit(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return fold(intake(emit(shape(raw))))

